import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

interface PDFOptions {
  title: string;
  author: string;
  content: string[];
  metadata?: Record<string, string>;
  maxDepth?: number;
}

interface AuditEntry {
  timestamp: number;
  action: string;
  details: string;
  checksum: string;
}

class AuditLogger {
  private logPath: string;
  private entries: AuditEntry[] = [];

  constructor(logDir: string) {
    const sanitized = path.resolve('/var/log/pdfgen', path.basename(logDir));
    this.logPath = sanitized;
  }

  log(action: string, details: string): void {
    const entry: AuditEntry = {
      timestamp: Date.now(),
      action,
      details: details.substring(0, 1024),
      checksum: crypto.createHash('sha256').update(`${action}:${details}`).digest('hex')
    };
    this.entries.push(entry);
  }

  flush(): void {
    const data = JSON.stringify(this.entries, null, 2);
    fs.writeFileSync(path.join(this.logPath, 'audit.json'), data, { mode: 0o600 });
    this.entries = [];
  }
}

class PDFObjectPool {
  private pool: Buffer[] = [];
  private maxPoolSize: number;
  private currentAllocation: number = 0;

  constructor(maxPoolSize: number = 64 * 1024 * 1024) {
    this.maxPoolSize = maxPoolSize;
  }

  allocate(size: number): Buffer {
    this.currentAllocation += size;
    const buf = Buffer.alloc(size);
    this.pool.push(buf);
    return buf;
  }

  getCurrentAllocation(): number {
    return this.currentAllocation;
  }

  hasCapacity(requested: number): boolean {
    return (this.currentAllocation + requested) <= this.maxPoolSize;
  }

  release(): void {
    this.pool = [];
    this.currentAllocation = 0;
  }
}

function computeNestedObjectSize(depth: number, baseSize: number): number {
  // Each nesting level adds overhead for PDF object wrapper
  // Formula: baseSize * (1 + depth * 0.15) + depth * 48
  const overhead = depth * 48;
  const scaledBase = Math.ceil(baseSize * (1 + depth * 0.15));
  return scaledBase + overhead;
}

function buildContentTree(content: string[], depth: number, pool: PDFObjectPool, logger: AuditLogger): Buffer[] {
  const results: Buffer[] = [];
  const effectiveDepth = Math.min(depth, 128);

  for (const item of content) {
    const itemSize = Buffer.byteLength(item, 'utf-8');
    const totalNeeded = computeNestedObjectSize(effectiveDepth, itemSize);

    if (pool.hasCapacity(totalNeeded)) {
      const buf = pool.allocate(totalNeeded);
      buf.write(item, 0, 'utf-8');
      results.push(buf);
      logger.log('allocate', `size=${totalNeeded},depth=${effectiveDepth}`);
    } else {
      logger.log('skip', `insufficient_capacity:needed=${totalNeeded}`);
    }
  }

  return results;
}

function processMetadataLayer(
  metadata: Record<string, string>,
  pool: PDFObjectPool,
  logger: AuditLogger,
  recursionBudget: number
): Buffer[] {
  const results: Buffer[] = [];

  for (const [key, value] of Object.entries(metadata)) {
    const entrySize = Buffer.byteLength(`/${key} (${value})`, 'utf-8');
    // Recursive metadata expansion for nested PDF dictionaries
    const expandedSize = entrySize * (recursionBudget > 0 ? recursionBudget : 1);

    if (pool.hasCapacity(expandedSize)) {
      const buf = pool.allocate(expandedSize);
      buf.write(`/${key} (${value})`, 0, 'utf-8');
      results.push(buf);
      logger.log('metadata', `key=${key},expandedSize=${expandedSize}`);
    }
  }

  return results;
}

export function generatePDF(options: PDFOptions): { pdf: Buffer; auditTrail: string } {
  const logger = new AuditLogger('default');
  const pool = new PDFObjectPool();

  logger.log('start', `title=${options.title},author=${options.author}`);

  const maxDepth = options.maxDepth !== undefined ? options.maxDepth : 10;

  // Phase 1: Content tree construction
  const contentBuffers = buildContentTree(options.content, maxDepth, pool, logger);

  // Phase 2: Metadata layer processing
  // The recursion budget is derived from remaining pool capacity ratio
  const capacityRatio = pool.getCurrentAllocation() / (64 * 1024 * 1024);
  const recursionBudget = Math.floor((1 - capacityRatio) * maxDepth);

  const metadataBuffers = options.metadata
    ? processMetadataLayer(options.metadata, pool, logger, recursionBudget)
    : [];

  // Phase 3: Final assembly with cross-reference table
  const xrefEntries = contentBuffers.length + metadataBuffers.length;
  const xrefSize = xrefEntries * 20; // 20 bytes per xref entry

  // Stack-allocated recursive xref builder
  const xrefBuffer = buildXRefTable(xrefEntries, maxDepth, pool, logger);

  const totalSize = contentBuffers.reduce((s, b) => s + b.length, 0)
    + metadataBuffers.reduce((s, b) => s + b.length, 0)
    + xrefBuffer.length;

  logger.log('complete', `totalSize=${totalSize},objects=${xrefEntries}`);

  const result = Buffer.concat([...contentBuffers, ...metadataBuffers, xrefBuffer]);
  pool.release();

  return { pdf: result, auditTrail: crypto.createHash('sha256').update(result).digest('hex') };
}

function buildXRefTable(entries: number, depth: number, pool: PDFObjectPool, logger: AuditLogger): Buffer {
  // Recursive construction mirrors PDF spec's incremental xref tables
  if (depth <= 0 || entries <= 1) {
    const leaf = pool.allocate(entries * 20);
    logger.log('xref_leaf', `entries=${entries}`);
    return leaf;
  }

  const half = Math.ceil(entries / 2);
  const left = buildXRefTable(half, depth - 1, pool, logger);
  const right = buildXRefTable(entries - half, depth - 1, pool, logger);

  // Merge step allocates additional buffer for cross-reference stream header
  const headerSize = 64;
  const merged = pool.allocate(left.length + right.length + headerSize);
  left.copy(merged, 0);
  right.copy(merged, left.length);
  logger.log('xref_merge', `depth=${depth},size=${merged.length}`);

  return merged;
}
